// up, right, down, left (clockwise order)
val DIRS4 = arrayOf(intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(1, 0), intArrayOf(0, -1))

// four sides plus four diagonals
val DIRS8 = arrayOf(
    intArrayOf(-1, -1), intArrayOf(-1, 0), intArrayOf(-1, 1),
    intArrayOf(0, -1),                      intArrayOf(0, 1),
    intArrayOf(1, -1),  intArrayOf(1, 0),  intArrayOf(1, 1)
)

fun inBounds(r: Int, c: Int, rows: Int, cols: Int): Boolean =
    r in 0 until rows && c in 0 until cols

// Usage
fun neighborSum(grid: Array<IntArray>, r: Int, c: Int): Int {
    var sum = 0
    for ((dr, dc) in DIRS8) {
        val nr = r + dr
        val nc = c + dc
        if (inBounds(nr, nc, grid.size, grid[0].size)) sum += grid[nr][nc]
    }
    return sum
}

fun spiralOrder(matrix: Array<IntArray>): List<Int> {
    val result = ArrayList<Int>()
    if (matrix.isEmpty()) return result
    var top = 0
    var bottom = matrix.size - 1
    var left = 0
    var right = matrix[0].size - 1

    while (top <= bottom && left <= right) {
        for (c in left..right) result.add(matrix[top][c])             // top row, left to right
        top++
        for (r in top..bottom) result.add(matrix[r][right])           // right column, top to bottom
        right--
        if (top <= bottom) {                                          // avoid repeating a single row
            for (c in right downTo left) result.add(matrix[bottom][c])
            bottom--
        }
        if (left <= right) {                                          // avoid repeating a single column
            for (r in bottom downTo top) result.add(matrix[r][left])
            left++
        }
    }
    return result
}
// Time: O(rows * cols)   Space: O(1) beyond the output

fun spiralOrderTurning(matrix: Array<IntArray>): List<Int> {
    val rows = matrix.size
    val cols = matrix[0].size
    val visited = Array(rows) { BooleanArray(cols) }
    val dr = intArrayOf(0, 1, 0, -1)                     // right, down, left, up
    val dc = intArrayOf(1, 0, -1, 0)
    val result = ArrayList<Int>()
    var r = 0
    var c = 0
    var d = 0
    repeat(rows * cols) {
        result.add(matrix[r][c])
        visited[r][c] = true
        val nr = r + dr[d]
        val nc = c + dc[d]
        if (nr !in 0 until rows || nc !in 0 until cols || visited[nr][nc]) {
            d = (d + 1) % 4                              // turn clockwise at a wall or a visited cell
        }
        r += dr[d]
        c += dc[d]
    }
    return result
}
// Time: O(rows * cols)   Space: O(rows * cols) for visited
// No special cases for thin matrices, but uses extra memory

fun antiDiagonals(matrix: Array<IntArray>): List<List<Int>> {
    val rows = matrix.size
    val cols = matrix[0].size
    val result = ArrayList<List<Int>>()
    for (s in 0..rows + cols - 2) {                       // s = r + c
        val line = ArrayList<Int>()
        for (r in maxOf(0, s - cols + 1)..minOf(s, rows - 1)) {
            line.add(matrix[r][s - r])
        }
        result.add(line)
    }
    return result
}

fun mainDiagonals(matrix: Array<IntArray>): List<List<Int>> {
    val rows = matrix.size
    val cols = matrix[0].size
    val result = ArrayList<List<Int>>()
    for (d in -(rows - 1) until cols) {                   // d = c - r
        val line = ArrayList<Int>()
        for (r in maxOf(0, -d)..minOf(rows - 1, cols - 1 - d)) {
            line.add(matrix[r][r + d])
        }
        result.add(line)
    }
    return result
}
// Time: O(rows * cols)   Space: O(rows * cols) for the output

fun rotate(matrix: Array<IntArray>) {
    val n = matrix.size
    for (i in 0 until n) {                                // transpose: swap across the main diagonal
        for (j in i + 1 until n) {
            val tmp = matrix[i][j]
            matrix[i][j] = matrix[j][i]
            matrix[j][i] = tmp
        }
    }
    for (row in matrix) row.reverse()                     // then reverse each row
}
// Time: O(n²)   Space: O(1)

fun rotateLayers(matrix: Array<IntArray>) {
    val n = matrix.size
    for (layer in 0 until n / 2) {
        val first = layer
        val last = n - 1 - layer
        for (i in first until last) {
            val offset = i - first
            val top = matrix[first][i]
            matrix[first][i] = matrix[last - offset][first]               // left to top
            matrix[last - offset][first] = matrix[last][last - offset]    // bottom to left
            matrix[last][last - offset] = matrix[i][last]                 // right to bottom
            matrix[i][last] = top                                         // top to right
        }
    }
}
// Time: O(n²)   Space: O(1)
// Each group of four cells moves in a cycle

fun setZeroes(matrix: Array<IntArray>) {
    val rows = matrix.size
    val cols = matrix[0].size
    var firstRowZero = false
    var firstColZero = false
    for (c in 0 until cols) if (matrix[0][c] == 0) firstRowZero = true
    for (r in 0 until rows) if (matrix[r][0] == 0) firstColZero = true

    for (r in 1 until rows) {                              // record which rows and columns need zeroing
        for (c in 1 until cols) {
            if (matrix[r][c] == 0) {
                matrix[r][0] = 0
                matrix[0][c] = 0
            }
        }
    }
    for (r in 1 until rows) {                              // apply the flags
        for (c in 1 until cols) {
            if (matrix[r][0] == 0 || matrix[0][c] == 0) matrix[r][c] = 0
        }
    }
    if (firstRowZero) for (c in 0 until cols) matrix[0][c] = 0
    if (firstColZero) for (r in 0 until rows) matrix[r][0] = 0
}
// Time: O(rows * cols)   Space: O(1)

fun searchMatrix(matrix: Array<IntArray>, target: Int): Boolean {
    var r = 0
    var c = matrix[0].size - 1                             // start at the top-right corner
    while (r < matrix.size && c >= 0) {
        when {
            matrix[r][c] == target -> return true
            matrix[r][c] > target -> c--                   // everything below in this column is bigger: move left
            else -> r++                                    // everything to the left in this row is smaller: move down
        }
    }
    return false
}
// Time: O(rows + cols)   Space: O(1)
// The top-right (or bottom-left) corner is the only start with a clear decision at every step

// Store the next state in a higher bit so neighbors can still read the current state.
// bit 0 = current state, bit 1 = next state
fun gameOfLife(board: Array<IntArray>) {
    val rows = board.size
    val cols = board[0].size
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            var live = 0
            for (dr in -1..1) {
                for (dc in -1..1) {
                    if (dr == 0 && dc == 0) continue
                    val nr = r + dr
                    val nc = c + dc
                    if (nr in 0 until rows && nc in 0 until cols) live += board[nr][nc] and 1   // read bit 0 only
                }
            }
            if (board[r][c] == 1 && (live == 2 || live == 3)) board[r][c] = board[r][c] or 2
            if (board[r][c] == 0 && live == 3) board[r][c] = board[r][c] or 2
        }
    }
    for (r in 0 until rows) {
        for (c in 0 until cols) board[r][c] = board[r][c] shr 1     // move the next state into place
    }
}
// Time: O(rows * cols * 8)   Space: O(1)

fun generateMatrix(n: Int): Array<IntArray> {
    val matrix = Array(n) { IntArray(n) }
    var top = 0
    var bottom = n - 1
    var left = 0
    var right = n - 1
    var num = 1
    while (top <= bottom && left <= right) {
        for (c in left..right) matrix[top][c] = num++
        top++
        for (r in top..bottom) matrix[r][right] = num++
        right--
        if (top <= bottom) {
            for (c in right downTo left) matrix[bottom][c] = num++
            bottom--
        }
        if (left <= right) {
            for (r in bottom downTo top) matrix[r][left] = num++
            left++
        }
    }
    return matrix
}
// Time: O(n²)   Space: O(1) beyond the output

fun transpose(matrix: Array<IntArray>): Array<IntArray> {
    val rows = matrix.size
    val cols = matrix[0].size
    val result = Array(cols) { IntArray(rows) }           // dimensions swap for a non-square matrix
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            result[c][r] = matrix[r][c]
        }
    }
    return result
}
// Time: O(rows * cols)   Space: O(rows * cols)
// A square matrix can be transposed in place, a rectangular one cannot

fun findDiagonalOrder(mat: Array<IntArray>): IntArray {
    val rows = mat.size
    val cols = mat[0].size
    val result = IntArray(rows * cols)
    var r = 0
    var c = 0
    for (i in result.indices) {
        result[i] = mat[r][c]
        if ((r + c) % 2 == 0) {                            // moving up and to the right
            when {
                c == cols - 1 -> r++                       // hit the right wall: go down
                r == 0 -> c++                              // hit the top wall: go right
                else -> { r--; c++ }
            }
        } else {                                           // moving down and to the left
            when {
                r == rows - 1 -> c++                       // hit the bottom wall: go right
                c == 0 -> r++                              // hit the left wall: go down
                else -> { r++; c-- }
            }
        }
    }
    return result
}
// Time: O(rows * cols)   Space: O(1) beyond the output

fun countNegatives(grid: Array<IntArray>): Int {
    val cols = grid[0].size
    var count = 0
    var r = grid.size - 1
    var c = 0                                              // start at the bottom-left corner
    while (r >= 0 && c < cols) {
        if (grid[r][c] < 0) {
            count += cols - c                              // this and everything to its right are negative
            r--                                            // go up to a larger row
        } else {
            c++                                            // go right to a smaller value
        }
    }
    return count
}
// Time: O(rows + cols)   Space: O(1)
// Rows and columns are sorted in non-increasing order

fun isValidSudoku(board: Array<CharArray>): Boolean {
    val rows = Array(9) { BooleanArray(9) }
    val cols = Array(9) { BooleanArray(9) }
    val boxes = Array(9) { BooleanArray(9) }
    for (r in 0 until 9) {
        for (c in 0 until 9) {
            val ch = board[r][c]
            if (ch == '.') continue
            val d = ch - '1'                               // digit 1..9 becomes index 0..8
            val b = (r / 3) * 3 + c / 3                    // which 3 x 3 box
            if (rows[r][d] || cols[c][d] || boxes[b][d]) return false
            rows[r][d] = true
            cols[c][d] = true
            boxes[b][d] = true
        }
    }
    return true
}
// Time: O(81)   Space: O(81)

fun isToeplitzMatrix(matrix: Array<IntArray>): Boolean {
    for (r in 1 until matrix.size) {
        for (c in 1 until matrix[0].size) {
            if (matrix[r][c] != matrix[r - 1][c - 1]) return false   // each cell equals its upper-left neighbor
        }
    }
    return true
}
// Time: O(rows * cols)   Space: O(1)

import java.util.PriorityQueue

fun diagonalSort(mat: Array<IntArray>): Array<IntArray> {
    val rows = mat.size
    val cols = mat[0].size
    val diagonals = HashMap<Int, PriorityQueue<Int>>()
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            diagonals.getOrPut(r - c) { PriorityQueue() }.add(mat[r][c])   // key r - c identifies a diagonal
        }
    }
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            mat[r][c] = diagonals[r - c]!!.poll()                           // smallest first
        }
    }
    return mat
}
// Time: O(rows * cols * log(min(rows, cols)))   Space: O(rows * cols)

fun flipAndInvertImage(image: Array<IntArray>): Array<IntArray> {
    for (row in image) {
        var l = 0
        var r = row.size - 1
        while (l <= r) {
            val a = row[l] xor 1                          // invert while swapping
            val b = row[r] xor 1
            row[l] = b
            row[r] = a
            l++
            r--
        }
    }
    return image
}
// Time: O(rows * cols)   Space: O(1)
// When l == r the middle cell is inverted once, which is correct

fun luckyNumbers(matrix: Array<IntArray>): List<Int> {
    val rows = matrix.size
    val cols = matrix[0].size
    val rowMin = IntArray(rows) { r -> matrix[r].minOrNull()!! }
    val colMax = IntArray(cols) { c -> (0 until rows).maxOf { r -> matrix[r][c] } }
    val result = mutableListOf<Int>()
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            if (matrix[r][c] == rowMin[r] && matrix[r][c] == colMax[c]) result.add(matrix[r][c])
        }
    }
    return result
}
// Time: O(rows * cols)   Space: O(rows + cols)

fun islandPerimeter(grid: Array<IntArray>): Int {
    var perimeter = 0
    for (r in grid.indices) {
        for (c in grid[0].indices) {
            if (grid[r][c] == 1) {
                perimeter += 4                                    // each land cell starts with 4 edges
                if (r > 0 && grid[r - 1][c] == 1) perimeter -= 2  // a shared edge hides 2 sides
                if (c > 0 && grid[r][c - 1] == 1) perimeter -= 2
            }
        }
    }
    return perimeter
}
// Time: O(rows * cols)   Space: O(1)
// Only look up and left, so each shared edge is counted once

fun imageSmoother(img: Array<IntArray>): Array<IntArray> {
    val rows = img.size
    val cols = img[0].size
    val result = Array(rows) { IntArray(cols) }
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            var sum = 0
            var count = 0
            for (dr in -1..1) {
                for (dc in -1..1) {
                    val nr = r + dr
                    val nc = c + dc
                    if (nr in 0 until rows && nc in 0 until cols) {
                        sum += img[nr][nc]
                        count++
                    }
                }
            }
            result[r][c] = sum / count                         // integer division rounds down
        }
    }
    return result
}
// Time: O(rows * cols * 9)   Space: O(rows * cols)
// A separate output array is needed so updated cells do not affect neighbors

fun diagonalSum(mat: Array<IntArray>): Int {
    val n = mat.size
    var sum = 0
    for (i in 0 until n) {
        sum += mat[i][i]                                      // main diagonal
        sum += mat[i][n - 1 - i]                              // anti-diagonal
    }
    if (n % 2 == 1) sum -= mat[n / 2][n / 2]                  // the center was counted twice
    return sum
}
// Time: O(n)   Space: O(1)

fun rotateCounterclockwise(matrix: Array<IntArray>) {
    val n = matrix.size
    for (row in matrix) row.reverse()                         // reverse each row first
    for (i in 0 until n) {                                    // then transpose
        for (j in i + 1 until n) {
            val tmp = matrix[i][j]
            matrix[i][j] = matrix[j][i]
            matrix[j][i] = tmp
        }
    }
}

fun rotate180(matrix: Array<IntArray>) {
    matrix.reverse()                                          // reverse the order of the rows
    for (row in matrix) row.reverse()                         // and each row
}
// Time: O(n²)   Space: O(1)

fun boundaryCells(matrix: Array<IntArray>): List<Int> {
    val rows = matrix.size
    val cols = matrix[0].size
    val result = ArrayList<Int>()
    if (rows == 1) { for (c in 0 until cols) result.add(matrix[0][c]); return result }
    if (cols == 1) { for (r in 0 until rows) result.add(matrix[r][0]); return result }
    for (c in 0 until cols) result.add(matrix[0][c])                     // top row
    for (r in 1 until rows) result.add(matrix[r][cols - 1])              // right column
    for (c in cols - 2 downTo 0) result.add(matrix[rows - 1][c])         // bottom row
    for (r in rows - 2 downTo 1) result.add(matrix[r][0])                // left column
    return result
}
// Time: O(rows + cols)   Space: O(rows + cols) for the output
